import json
import os

OUTPUT_DIR = os.path.join(os.path.dirname(__file__), "..", "public", "data")
q_file = os.path.join(OUTPUT_DIR, "questions.json")

with open(q_file, "r", encoding="utf-8") as f:
    questions = json.load(f)

qid = len(questions) + 1

def add_q(category, module, badge, source, q_en, q_hi, opts_en, opts_hi, correct_idx, diff, sol_en, sol_hi, tip, trap, tags):
    global qid
    questions.append({
        "id": f"CA-{qid:04d}",
        "category": category,
        "module": module,
        "badge": badge,
        "source": source,
        "question": q_en,
        "questionHindi": q_hi,
        "options": opts_en,
        "optionsHindi": opts_hi,
        "correctOption": correct_idx,
        "difficulty": diff,
        "solution": sol_en,
        "solutionHindi": sol_hi,
        "conceptTip": tip,
        "trapAlert": trap,
        "tags": tags
    })
    qid += 1

