        q_en=q_en,
        q_hi=q_hi,
        opts_en=arranged,
        opts_hi=arranged,
        correct_idx=arranged.index(correct_val),
        diff="Medium",
        sol_en=expl,
        sol_hi=expl,
        tip=f"Core concept in {mod}.",
        trap="Read the question carefully to distinguish subtle distinctions.",
        tags=[cat.lower(), mod.lower().replace(" ", "-")]
